525→// findSessionIndex returns the index of an existing session with the given ID,
526→// or the next available index if not found. This prevents duplicate session entries.
527→func (s *GitStore) findSessionIndex(ctx context.Context, basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
528→	if existingSummary == nil {
529→		return 0
530→	}
531→	for i := range len(existingSummary.Sessions) {
532→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
533→		if entry, exists := entries[path]; exists {
534→			meta, err := s.readMetadataFromBlob(entry.Hash)
535→			if err != nil {
536→				logging.Warn(ctx, "failed to read session metadata during dedup check",
537→					slog.Int("session_index", i),
538→					slog.String("session_id", sessionID),
539→					slog.String("error", err.Error()),
540→				)
541→				continue
542→			}
543→			if meta.SessionID == sessionID {
544→				return i
545→			}
546→		}
547→	}
548→	return len(existingSummary.Sessions)
549→}
