551→// reaggregateFromEntries reads all session metadata from the entries map and
552→// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
553→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
554→	var totalCount int
555→	var allFiles []string
556→	var totalTokens *agent.TokenUsage
557→
558→	for i := range sessionCount {
559→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
560→		entry, exists := entries[path]
561→		if !exists {
562→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
563→		}
564→		meta, err := s.readMetadataFromBlob(entry.Hash)
565→		if err != nil {
566→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
567→		}
568→		totalCount += meta.CheckpointsCount
569→		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
570→		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
571→	}
572→
573→	return totalCount, allFiles, totalTokens, nil
574→}
