576→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
577→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
578→	blob, err := repo.BlobObject(hash)
579→	if err != nil {
580→		return nil, fmt.Errorf("failed to get blob: %w", err)
581→	}
582→
583→	reader, err := blob.Reader()
584→	if err != nil {
585→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
586→	}
587→	defer reader.Close()
588→
589→	var result T
590→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
591→		return nil, fmt.Errorf("failed to decode: %w", err)
592→	}
593→
594→	return &result, nil
595→}
