682→// mergeFilesTouched combines two file lists, removing duplicates.
683→// All paths are normalized to forward slashes for platform-agnostic storage.
684→func mergeFilesTouched(existing, additional []string) []string {
685→	seen := make(map[string]bool)
686→	var result []string
687→
688→	for _, f := range existing {
689→		f = filepath.ToSlash(f)
690→		if !seen[f] {
691→			seen[f] = true
692→			result = append(result, f)
693→		}
694→	}
695→	for _, f := range additional {
696→		f = filepath.ToSlash(f)
697→		if !seen[f] {
698→			seen[f] = true
699→			result = append(result, f)
700→		}
701→	}
702→
703→	sort.Strings(result)
704→	return result
705→}
