808→// ReadCommitted reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
809→// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
810→// Use ReadSessionContent to read actual transcript/prompts/context.
811→// Returns nil, nil if the checkpoint doesn't exist.
812→//
813→// The storage format uses numbered subdirectories for each session (0-based):
814→//
815→//	<checkpoint-id>/
816→//	├── metadata.json      # CheckpointSummary with sessions map
817→//	├── 0/                 # First session
818→//	│   ├── metadata.json  # Session-specific metadata
819→//	│   └── full.jsonl     # Transcript
820→//	├── 1/                 # Second session
821→//	└── ...
822→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
823→	if err := ctx.Err(); err != nil {
824→		return nil, err //nolint:wrapcheck // Propagating context cancellation
825→	}
826→
827→	ft, err := s.getFetchingTree(ctx)
828→	if err != nil {
829→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
830→	}
831→
832→	checkpointPath := checkpointID.Path()
833→	checkpointTree, err := ft.Tree(checkpointPath)
834→	if err != nil {
835→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
836→	}
837→
838→	// Read root metadata.json as CheckpointSummary (auto-fetches blob if needed)
839→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
840→	if err != nil {
841→		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
842→	}
843→
844→	content, err := metadataFile.Contents()
845→	if err != nil {
846→		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
847→	}
848→
849→	var summary CheckpointSummary
850→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
851→		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
852→	}
853→
854→	return &summary, nil
855→}
