895→// ReadSessionContent reads the actual content for a specific session within a checkpoint.
896→// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
897→// Returns the session's metadata, transcript, prompts, and context.
898→// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist.
899→// Returns ErrNoTranscript if the session exists but has no transcript.
900→func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
901→	if err := ctx.Err(); err != nil {
902→		return nil, err //nolint:wrapcheck // Propagating context cancellation
903→	}
904→
905→	ft, err := s.getFetchingTree(ctx)
906→	if err != nil {
907→		return nil, ErrCheckpointNotFound
908→	}
909→
910→	checkpointPath := checkpointID.Path()
911→	checkpointTree, err := ft.Tree(checkpointPath)
912→	if err != nil {
913→		return nil, ErrCheckpointNotFound
914→	}
915→
916→	// Get the session subdirectory
917→	sessionDir := strconv.Itoa(sessionIndex)
918→	sessionTree, err := checkpointTree.Tree(sessionDir)
919→	if err != nil {
920→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
921→	}
922→
923→	result := &SessionContent{}
924→
925→	// Read session-specific metadata (auto-fetches blob if needed)
926→	var agentType types.AgentType
927→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
928→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
929→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
930→				agentType = result.Metadata.Agent
931→			}
932→		}
933→	}
934→
935→	// Read transcript (auto-fetches blobs if needed)
936→	if transcript, transcriptErr := readTranscriptFromTree(ctx, sessionTree, agentType); transcriptErr == nil && transcript != nil {
937→		result.Transcript = transcript
938→	}
939→
940→	// Read prompts (auto-fetches blob if needed)
941→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
942→		if content, contentErr := file.Contents(); contentErr == nil {
943→			result.Prompts = content
944→		}
945→	}
946→
947→	if len(result.Transcript) == 0 {
948→		return nil, ErrNoTranscript
949→	}
950→
951→	return result, nil
952→}
