1430→// CreateBlobFromContent creates a blob object from in-memory content.
1431→// Exported for use by strategy package (session_test.go)
1432→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1433→	obj := repo.Storer.NewEncodedObject()
1434→	obj.SetType(plumbing.BlobObject)
1435→	obj.SetSize(int64(len(content)))
1436→
1437→	writer, err := obj.Writer()
1438→	if err != nil {
1439→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
1440→	}
1441→
1442→	_, err = writer.Write(content)
1443→	if err != nil {
1444→		_ = writer.Close()
1445→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
1446→	}
1447→	if err := writer.Close(); err != nil {
1448→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
1449→	}
1450→
1451→	hash, err := repo.Storer.SetEncodedObject(obj)
1452→	if err != nil {
1453→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
1454→	}
1455→	return hash, nil
1456→}
