1458→// copyMetadataDir copies all files from a directory to the checkpoint path.
1459→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
1460→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
1461→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
1462→		if err != nil {
1463→			return err
1464→		}
1465→
1466→		// Skip symlinks to prevent reading files outside the metadata directory.
1467→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
1468→		// then be captured in the checkpoint and stored in git history.
1469→		// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
1470→		// reports ModeSymlink. We use os.Lstat to check the entry itself.
1471→		// This check MUST come before IsDir() because Walk follows symlinked
1472→		// directories and would recurse into them otherwise.
1473→		linfo, lstatErr := os.Lstat(path)
1474→		if lstatErr != nil {
1475→			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
1476→		}
1477→		if linfo.Mode()&os.ModeSymlink != 0 {
1478→			if info.IsDir() {
1479→				return filepath.SkipDir
1480→			}
1481→			return nil
1482→		}
1483→
1484→		if info.IsDir() {
1485→			return nil
1486→		}
1487→
1488→		// Get relative path within metadata dir
1489→		relPath, err := filepath.Rel(metadataDir, path)
1490→		if err != nil {
1491→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
1492→		}
1493→
1494→		// Prevent path traversal via symlinks pointing outside the metadata dir
1495→		if strings.HasPrefix(relPath, "..") {
1496→			return fmt.Errorf("path traversal detected: %s", relPath)
1497→		}
1498→
1499→		// Create blob from file with secrets redaction
1500→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
1501→		if err != nil {
1502→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
1503→		}
1504→
1505→		// Store at checkpoint path (use forward slashes for git tree compatibility on Windows)
1506→		fullPath := basePath + filepath.ToSlash(relPath)
1507→		entries[fullPath] = object.TreeEntry{
1508→			Name: fullPath,
1509→			Mode: mode,
1510→			Hash: blobHash,
1511→		}
1512→
1513→		return nil
1514→	})
1515→	if err != nil {
1516→		return fmt.Errorf("failed to walk metadata directory: %w", err)
1517→	}
1518→	return nil
1519→}
