1521→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1522→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1523→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1524→	info, err := os.Stat(filePath)
1525→	if err != nil {
1526→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1527→	}
1528→
1529→	mode := filemode.Regular
1530→	if info.Mode()&0o111 != 0 {
1531→		mode = filemode.Executable
1532→	}
1533→
1534→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1535→	if err != nil {
1536→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1537→	}
1538→
1539→	// Skip redaction for binary files — they can't contain text secrets and
1540→	// running string replacement on them would corrupt the data.
1541→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1542→	if binErr != nil || isBin {
1543→		hash, err := CreateBlobFromContent(repo, content)
1544→		if err != nil {
1545→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1546→		}
1547→		return hash, mode, nil
1548→	}
1549→
1550→	if strings.HasSuffix(treePath, ".jsonl") {
1551→		redacted, jsonlErr := redact.JSONLBytes(content)
1552→		if jsonlErr != nil {
1553→			redacted = redact.Bytes(content)
1554→		}
1555→		content = redacted
1556→	} else {
1557→		content = redact.Bytes(content)
1558→	}
1559→
1560→	hash, err := CreateBlobFromContent(repo, content)
1561→	if err != nil {
1562→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1563→	}
1564→	return hash, mode, nil
1565→}
